package dev.sablelife.testing;
import dev.sablelife.module.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
@GameTestHolder("sablelife_summon_tests") @PrefixGameTestTemplate(false)
public final class SummonTargetCacheGameTests {
 private static net.minecraft.world.entity.animal.Cow cow(GameTestHelper h,Vec3 center){var e=EntityType.COW.create(h.getLevel());e.setNoAi(true);e.setNoGravity(true);e.setPos(center.subtract(0,e.getBbHeight()/2,0));h.getLevel().addFreshEntity(e);return e;}
 @GameTest(template="combat",batch="summon_cache_shared") public static void Overlapping32MemberSearchesShareOnePoolAndSelectIndependently(GameTestHelper h){var origin=h.absoluteVec(new Vec3(6,25,6));var left=cow(h,origin.add(-3,0,4));var right=cow(h,origin.add(3,0,4));try{var cache=new SummonTargetCache();var points=new ArrayList<Vec3>();for(int i=0;i<32;i++)points.add(origin.add((i-15.5)/8,0,0));var owner=UUID.randomUUID();cache.prepare(h.getLevel(),owner,1,points,8,0);h.assertTrue(cache.queries()==1,"32 overlapping weapons performed duplicate spatial searches");h.assertTrue(cache.select(null,points.getFirst(),8,true).equals(left.getUUID())&&cache.select(null,points.getLast(),8,true).equals(right.getUUID()),"Shared pool forced one target on all weapons");for(int tick=1;tick<5;tick++)cache.prepare(h.getLevel(),owner,1,points,8,tick);h.assertTrue(cache.queries()==1,"Pool searched between refresh ticks");cache.prepare(h.getLevel(),owner,1,points,8,5);h.assertTrue(cache.queries()==2,"Pool did not refresh on tick 5");}finally{left.discard();right.discard();}h.succeed();}
 @GameTest(template="combat",batch="summon_cache_live") public static void LivePositionsDeathRangeAndNewArrivalsDoNotRequirePerWeaponSearches(GameTestHelper h){var origin=h.absoluteVec(new Vec3(6,25,6));var first=cow(h,origin.add(1,0,2));var second=cow(h,origin.add(4,0,2));net.minecraft.world.entity.animal.Cow arriving=null;try{var cache=new SummonTargetCache();var owner=UUID.randomUUID();cache.prepare(h.getLevel(),owner,1,List.of(origin),8,0);var chosen=cache.select(null,origin,8,true);h.assertTrue(chosen.equals(first.getUUID()),"Wrong initial target");first.setPos(first.position().add(0,0,1));cache.prepare(h.getLevel(),owner,1,List.of(origin),8,1);h.assertTrue(cache.queries()==1&&cache.point(chosen).distanceToSqr(first.getBoundingBox().getCenter())<1e-9,"Tracking position froze with the search pool");first.discard();h.assertTrue(cache.point(chosen)==null&&cache.select(chosen,origin,8,false).equals(second.getUUID()),"Dead/removed target remained selected within a tick");second.setPos(second.position().add(30,0,0));cache.prepare(h.getLevel(),owner,1,List.of(origin),8,2);h.assertTrue(cache.select(second.getUUID(),origin,8,false)==null&&cache.queries()==1,"Out-of-range target was retained or caused repeated searches");arriving=cow(h,origin.add(0,0,3));cache.prepare(h.getLevel(),owner,1,List.of(origin),8,4);h.assertTrue(cache.select(null,origin,8,true)==null,"New arrival was not using the bounded search schedule");cache.prepare(h.getLevel(),owner,1,List.of(origin),8,5);h.assertTrue(cache.select(null,origin,8,true).equals(arriving.getUUID())&&cache.queries()==2,"New arrival missed the next pool refresh");}finally{first.discard();second.discard();if(arriving!=null)arriving.discard();}h.succeed();}
 @GameTest(template="combat",batch="summon_cache_coverage") public static void MovementRequeriesImmediatelyAndSparseFormationsStayPartitioned(GameTestHelper h){var origin=h.absoluteVec(new Vec3(6,25,6));var cache=new SummonTargetCache();var owner=UUID.randomUUID();cache.prepare(h.getLevel(),owner,1,List.of(origin),2,0);cache.prepare(h.getLevel(),owner,1,List.of(origin.add(6,0,0)),2,1);h.assertTrue(cache.queries()==2,"Fast formation movement waited for the stale search area");var sparse=new SummonTargetCache();sparse.prepare(h.getLevel(),owner,1,List.of(origin,origin.add(20,0,20)),2,0);h.assertTrue(sparse.queries()==2,"Sparse formation scanned a giant empty union");sparse.prepare(h.getLevel(),owner,0,List.of(origin,origin.add(20,0,20)),2,1);h.assertTrue(sparse.queries()==4,"Target category change reused stale candidates");sparse.prepare(h.getLevel(),owner,0,List.of(),2,2);h.assertTrue(sparse.point(null)==null,"Suspended pool retained targets");h.succeed();}
 @GameTest(template="combat",batch="summon_cache_life") public static void MechanicalLifeDeathInvalidatesCachedAdapterImmediately(GameTestHelper h){var level=h.getLevel();var pos=h.absolutePos(new BlockPos(6,25,6));level.setBlockAndUpdate(pos,dev.sablelife.SableLife.HEART.get().defaultBlockState());var c=(dev.sablelife.heart.HeartBlockEntity)level.getBlockEntity(pos);c.health().activate();dev.sablelife.ownership.BodyOwnership.get(level).bind(pos,c.creatureId());dev.sablelife.ownership.LoadedCoreIndex.observe(c);var cache=new SummonTargetCache();var owner=UUID.randomUUID();cache.prepare(level,owner,3,List.of(pos.getCenter()),4,0);h.assertTrue(cache.select(null,pos.getCenter(),4,true).equals(c.creatureId()),"Life adapter absent from shared pool");c.forceDeath();h.assertTrue(cache.point(c.creatureId())==null,"Cached life adapter survived its core's death");cache.prepare(level,owner,3,List.of(pos.getCenter()),4,1);h.assertTrue(cache.select(c.creatureId(),pos.getCenter(),4,false)==null&&cache.queries()==1,"Dead core caused repeated world search or remained targeted");h.succeed();}
 @GameTest(template="combat",batch="summon_cache_runtime",timeoutTicks=25) public static void Actual32MemberGroupSharesSearchesWhileUpdatingAim(GameTestHelper h){var c=SlashGuardGameTests.core(h);var pin=c.modules().add("hover_anchor");pin.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.UP)));pin.edit("hoverRotation",1,"");var a=c.modules().add("gun");a.edit("enabled",0,"");a.edit("range",1,"");a.edit("interval",1000,"");var m=c.modules().add("summoned_weapon");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.NORTH)));m.projectileItem(new ItemStack(Items.CROSSBOW),h.getLevel().registryAccess());m.summonAttack(a.id());m.edit("summonCount",32,"");m.edit("summonFormation",5,"");m.edit("summonRadius",2,"");m.edit("summonAim",1,"");m.edit("target",1,"");m.edit("targetRange",8,"");var victim=cow(h,ModuleSummonedWeapon.position(c,m).add(0,0,-5));c.tryActivate(TestActors.creative(h.getLevel()));c.modules().tick(c);h.assertTrue(c.modules().summonedWeapons.frames(m.id()).size()==32&&c.modules().summonedWeapons.targetQueries(m.id())==1,"Runtime did not share the initial 32 searches");h.runAfterDelay(4,()->h.assertTrue(c.modules().summonedWeapons.targetQueries(m.id())==1,"Runtime still queried per weapon/tick"));h.runAfterDelay(6,()->{try{h.assertTrue(c.modules().summonedWeapons.targetQueries(m.id())==2,"Runtime pool refresh cadence incorrect");h.assertTrue(c.modules().summonedWeapons.frames(m.id()).size()==32,"Search optimization dropped weapons");c.modules().summonedWeapons.clear();h.succeed();}finally{victim.discard();}});}
}
